237	func (d *DB) DeleteMemo(ctx context.Context, delete *store.DeleteMemo) error {
238		where, args := []string{"`id` = ?"}, []any{delete.ID}
239		stmt := "DELETE FROM `memo` WHERE " + strings.Join(where, " AND ")
240		result, err := d.db.ExecContext(ctx, stmt, args...)
241		if err != nil {
242			return err
243		}
244		if _, err := result.RowsAffected(); err != nil {
245			return err
246		}
247		return nil
248	}
